    "id": 4,
    "category": "nature",
    "categoryTamil": "இயற்கை",
    "titleTamil": "மலைப் பிரதேசம்",
    "titleEnglish": "Mountain Misty Valley",
    "title": "மலைப் பிரதேசம்",
    "titleEn": "Mountain Misty Valley",
    "icon": "⛰️",
    "tagline": "பனிப்புகை மூடிய சிகரங்களும், பைன் மரங்களும் சூழ்ந்த குளிர்ந்த மலைப் பள்ளத்தாக்கின் அழகு.",
    "summary": "பனிப்புகை மூடிய சிகரங்களும், பைன் மரங்களும் சூழ்ந்த குளிர்ந்த மலைப் பள்ளத்தாக்கின் அழகு.",
