    "tagline": "மழை நின்ற பின் வானில் ஏழு வண்ணங்களில் வளைந்து நிற்கும் வானவில்லின் கண்கவர் காட்சி.",
    "summary": "மழை நின்ற பின் வானில் ஏழு வண்ணங்களில் வளைந்து நிற்கும் வானவில்லின் கண்கவர் காட்சி.",
