    "tagline": "நோயாளிகளுக்குக் கனிவான சிகிச்சையும் நம்பிக்கையும் அளிக்கும் மருத்துவமனையின் தூய்மையான சூழல்.",
    "summary": "நோயாளிகளுக்குக் கனிவான சிகிச்சையும் நம்பிக்கையும் அளிக்கும் மருத்துவமனையின் தூய்மையான சூழல்.",
