    "titleEn": "Annual Book Fair",
    "icon": "📖",
    "tagline": "அறிஞர்களும் வாசகர்களும் பல்லாயிரக்கணக்கான புத்தகங்களைச் சந்திக்கும் பிரம்மாண்ட புத்தகத் திருவிழா.",
    "summary": "அறிஞர்களும் வாசகர்களும் பல்லாயிரக்கணக்கான புத்தகங்களைச் சந்திக்கும் பிரம்மாண்ட புத்தகத் திருவிழா.",
