    "icon": "🔭",
    "tagline": "வட்ட வடிவக் கூரையில் விண்மீன்களும் கோள்களும் சுழலும் அறிவியல் கோளரங்கத்தின் விந்தை.",
    "summary": "வட்ட வடிவக் கூரையில் விண்மீன்களும் கோள்களும் சுழலும் அறிவியல் கோளரங்கத்தின் விந்தை.",
