    "tagline": "நோயாளிகளுக்கு இன்முகத்துடன் மருத்துவம் பார்த்து ஆறுதல் கூறும் அன்பான மருத்துவர்.",
    "summary": "நோயாளிகளுக்கு இன்முகத்துடன் மருத்துவம் பார்த்து ஆறுதல் கூறும் அன்பான மருத்துவர்.",
