    "tagline": "மிதிவண்டியில் கடிதப் பையுடன் ஊரெங்கும் மகிழ்ச்சியான செய்திகளைக் கொண்டுவரும் தபால்காரர்.",
    "summary": "மிதிவண்டியில் கடிதப் பையுடன் ஊரெங்கும் மகிழ்ச்சியான செய்திகளைக் கொண்டுவரும் தபால்காரர்.",
