    "id": 31,
    "category": "people",
    "categoryTamil": "மனிதர்கள்",
    "titleTamil": "கடலோர மீனவர்",
    "titleEnglish": "Brave Coastal Fisherman",
    "title": "கடலோர மீனவர்",
    "titleEn": "Brave Coastal Fisherman",
    "icon": "🎣",
    "tagline": "அதிகாலை அலையெழும் கடலில் படகைச் செலுத்தி மீன்பிடிக்கும் துணிச்சலான மீனவர்.",
    "summary": "அதிகாலை அலையெழும் கடலில் படகைச் செலுத்தி மீன்பிடிக்கும் துணிச்சலான மீனவர்.",
