    "titleEn": "Skilled Furniture Carpenter",
    "icon": "🪚",
    "tagline": "மரங்களை அறுத்து செதுக்கி அழகிய நாற்காலிகளும் மேஜைகளும் செய்யும் தச்சரின் திறமை.",
    "summary": "மரங்களை அறுத்து செதுக்கி அழகிய நாற்காலிகளும் மேஜைகளும் செய்யும் தச்சரின் திறமை.",
