    "titleEn": "Diligent Traffic Police Officer",
    "icon": "👮",
    "tagline": "வெயிலையும் புகையையும் பொருட்படுத்தாமல் சாலைப் போக்குவரத்தைச் சீர்செய்யும் துடிப்பான காவலர்.",
    "summary": "வெயிலையும் புகையையும் பொருட்படுத்தாமல் சாலைப் போக்குவரத்தைச் சீர்செய்யும் துடிப்பான காவலர்.",
