    "tagline": "வாலாட்டி அன்பை வெளிப்படுத்தி வீட்டின் பாதுகாப்பாக விளங்கும் செல்ல நாய் டாபி.",
    "summary": "வாலாட்டி அன்பை வெளிப்படுத்தி வீட்டின் பாதுகாப்பாக விளங்கும் செல்ல நாய் டாபி.",
