    "titleEn": "Dancing Peacock in the Rain",
    "icon": "🦚",
    "tagline": "மழைக்காலத்தில் நீல வண்ணத் தோகையை விசிறி போல விரித்து நடனமாடும் அழகிய மயில்.",
    "summary": "மழைக்காலத்தில் நீல வண்ணத் தோகையை விசிறி போல விரித்து நடனமாடும் அழகிய மயில்.",
