    "icon": "🐘",
    "tagline": "அடர்ந்த காடுகளில் தும்பிக்கையை அசைத்து கம்பீரமாக நடந்துசெல்லும் யானைக் கூட்டம்.",
    "summary": "அடர்ந்த காடுகளில் தும்பிக்கையை அசைத்து கம்பீரமாக நடந்துசெல்லும் யானைக் கூட்டம்.",
