    "tagline": "வளைந்த சிவப்பு மூக்கும் பச்சைப் பசேல் சிறகுகளும் கொண்டு மனிதர்களைப் போலப் பேசும் கிளி.",
    "summary": "வளைந்த சிவப்பு மூக்கும் பச்சைப் பசேல் சிறகுகளும் கொண்டு மனிதர்களைப் போலப் பேசும் கிளி.",
