    "icon": "🦌",
    "tagline": "வெள்ளைப் புள்ளிகளுடன் மெல்லிய கால்களைக் கொண்டு துள்ளி ஓடும் அழகிய புள்ளிமான்.",
    "summary": "வெள்ளைப் புள்ளிகளுடன் மெல்லிய கால்களைக் கொண்டு துள்ளி ஓடும் அழகிய புள்ளிமான்.",
