    "titleEn": "Grandfather Wall Clock",
    "icon": "🕰️",
    "tagline": "தாள லயத்தோடு ஊசல் அசைந்து ஒவ்வொரு மணிநேரமும் கம்பீரமாக மணியடிக்கும் பழைய கடிகாரம்.",
    "summary": "தாள லயத்தோடு ஊசல் அசைந்து ஒவ்வொரு மணிநேரமும் கம்பீரமாக மணியடிக்கும் பழைய கடிகாரம்.",
