    "tagline": "இரவு நேர அமைதியில் புத்தகப் பக்கங்களை ஒளிரச் செய்து படிப்பில் கவனத்தை ஈர்க்கும் மேஜை விளக்கு.",
    "summary": "இரவு நேர அமைதியில் புத்தகப் பக்கங்களை ஒளிரச் செய்து படிப்பில் கவனத்தை ஈர்க்கும் மேஜை விளக்கு.",
