    "title": "புகைப்படக் கருவி",
    "titleEn": "Vintage Lens Camera",
    "icon": "📷",
    "tagline": "அழகான தருணங்களையும் மனிதர்களின் புன்னகையையும் காலம் கடந்து பதிவு செய்யும் கேமரா.",
    "summary": "அழகான தருணங்களையும் மனிதர்களின் புன்னகையையும் காலம் கடந்து பதிவு செய்யும் கேமரா.",
