    "tagline": "இரவு வானில் தூரத்து கோள்களையும் நிலவின் பள்ளங்களையும் அருகில் காட்டும் தொலைநோக்கி.",
    "summary": "இரவு வானில் தூரத்து கோள்களையும் நிலவின் பள்ளங்களையும் அருகில் காட்டும் தொலைநோக்கி.",
