    "tagline": "தாகத்தைத் தணித்து உடலுக்குப் புத்துணர்ச்சியூட்டும் தூய குளிர்ந்த குடிநீரும் கண்ணாடி குவளையும்.",
    "summary": "தாகத்தைத் தணித்து உடலுக்குப் புத்துணர்ச்சியூட்டும் தூய குளிர்ந்த குடிநீரும் கண்ணாடி குவளையும்.",
