    "titleEn": "Planting Green Saplings",
    "icon": "🌱",
    "tagline": "வருங்கால தலைமுறைக்கு நாம் தரும் பசுமைப் பரிசு",
    "summary": "வருங்கால தலைமுறைக்கு நாம் தரும் பசுமைப் பரிசு",
    "badge": "நற்பழக்கங்கள்",
    "vocab": "மரக்கன்று (Tree sapling), மண் (Soil / Earth), மழை (Rain), சுற்றுச்சூழல் (Environment)",
