    "summary": "ஊரே திரண்டு வடம் பிடிக்கும் பக்தி பரவசப் பெருவிழா",
    "badge": "பண்டிகைகள்",
    "vocab": "திருத்தேர் (Temple chariot), வடம் பிடித்தல் (Pulling the chariot rope), பக்தி (Devotion), மேளதாளம் (Temple percussion / Drums)",
