    "summary": "அன்பையும் அமைதியையும் உலகிற்குப் பறைசாற்றும் குளிர்கால விழா",
    "badge": "பண்டிகைகள்",
    "vocab": "கிறிஸ்துமஸ் (Christmas), நட்சத்திரம் (Star), கிறிஸ்துமஸ் தாத்தா (Santa Claus), அமைதி (Peace)",
