    "summary": "இயற்கையின் புது உயிர் துளிர்க்கும் ஊட்டச்சத்துப் பெட்டகம்",
    "badge": "பாரம்பரிய உணவுகள்",
    "vocab": "முளைகட்டிய பயறு (Sprouted beans / Sprouts), தானியம் (Grains / Pulses), ஊட்டச்சத்து (Nutrients), நார்ச்சத்து (Fiber)",
