    "tagline": "பாறைகளின் ஊடே கசிந்து வரும் இயற்கையின் தூய ஜீவாமிர்தம்",
    "summary": "பாறைகளின் ஊடே கசிந்து வரும் இயற்கையின் தூய ஜீவாமிர்தம்",
